<template>
  <div class="page-login">
    <div class="left"></div>
    <div class="login-blk">
      <h2 class="title">AIOTEC边缘计算网关</h2>
      <el-form
        ref="loginFormRef"
        :model="loginForm"
        class="login-form"
        size="large"
        @keyup.enter.native="submitForm('loginFormRef')"
        :rules="formRules"
      >
        <el-form-item prop="user_name">
          <el-input
            v-model="loginForm.user_name"
            autocomplete="off"
            placeholder="用户名"
          />
        </el-form-item>
        <el-form-item prop="user_pwd">
          <el-input
            v-model="loginForm.user_pwd"
            placeholder="密码"
            type="password"
            autocomplete="off"
            show-password
          />
        </el-form-item>
        <div v-if="errmsg" class="fs-14" >
          <span style="color: red">{{ errmsg }}</span>
          <el-button type="text" class="ml-10" @click="goAuthorize"
            >去授权</el-button
          >
        </div>

        <el-form-item style="margin-top: 60px">
          <el-button
            style="width: 100%"
            plain
            type="primary"
            @click="submitForm('loginFormRef')"
          >
            <div>
              <span v-if="!loading">登录</span>
              <span v-else>正在登录<i class="el-icon-loading ml-5"></i></span>
            </div>
          </el-button>
        </el-form-item>
      </el-form>
    </div>
    <Authorize :isAuthorize="isAuthorize" @close="close" v-if="isAuthorize" />
  </div>
</template>

<script>
import Authorize from "@/components/authorize";

export default {
  components: {
    Authorize,
  },
  data() {
    return {
      loginForm: {},
      redirect: undefined,
      loading: false,
      formRules: {
        user_name: [
          { required: true, message: "请输入用户名", trigger: "blur" },
        ],
        user_pwd: [{ required: true, message: "请输入密码", trigger: "blur" }],
      },
      isAuthorize: false,
      errmsg: "",
    };
  },
  watch: {
    $route: {
      handler: function (route) {
        this.redirect = route.query && route.query.redirect;
      },
      immediate: true,
    },
  },
  methods: {
    goAuthorize() {
      this.isAuthorize = true;
    },
    close() {
      this.isAuthorize = false;
    },
    submitForm(formName) {
      this.$refs[formName].validate((valid) => {
        if (valid) {
          // 登录逻辑
          this.loading = true;
          this.$api
            .post("/user/login", this.loginForm)
            .then((res) => {
              localStorage.setItem("token", res.data.data);
              this.$router.push({ path: this.redirect || "/" });
            })
            .catch((err) => {
              this.errmsg = err.data.code == 3 ? err.data.msg : "";
            })
            .finally(() => {
              this.loading = false;
            });
        } else {
          return false;
        }
      });
    },
  },
};
</script>

